 260→    this.input.on('pointerup', () => {
 261→      if (this.detailPanel) return; // 상세 패널 열려있으면 hasDragged 초기화 무시
 262→      // card pointerup 이벤트가 먼저 발생하므로 다음 프레임에 초기화
 263→      this.time.delayedCall(0, () => {
 264→        this.hasDragged = false;
 265→        this.hasPointerDownInScene = false;
 266→      });
 267→    });
 268→
 269→    // 마우스 휠
 270→    this.input.on(
 271→      'wheel',
 272→      (_p: Phaser.Input.Pointer, _go: unknown[], _dx: number, deltaY: number) => {
 273→        if (this.detailPanel) return; // 상세 패널 열려있으면 휠 스크롤 무시
 274→        this.scrollOffset = Phaser.Math.Clamp(
 275→          this.scrollOffset + deltaY * 0.5,
 276→          0,
 277→          this.maxScrollOffset,
 278→        );
 279→        this.cardsContainer.setY(-this.scrollOffset);
 280→      },
 281→    );
 282→
 283→    // ── 고정 UI ─────────────────────────────────────────────────────────
 284→    this.createBackButton();
 285→
 286→    // maskGfx는 display list 외부에 있으므로 씬 종료 시 직접 정리
 287→    this.events.once('shutdown', () => { this.maskGfx.destroy(); });
 288→  }
