 404→  private createWallpaperCard(wp: BackgroundDef, x: number, y: number) {
 405→    const isOwned = this.ownedWpIds.includes(wp.id);
 406→    const isSelected = this.selectedWpId === wp.id;
 407→
 408→    // 카드 배경
 409→    const cardBg = this.add.rectangle(x, y, WP_CARD_W, WP_CARD_H, 0x1a1a2e);
 410→    cardBg.setStrokeStyle(2, isOwned ? WP_ACCENT_INT : 0x333333);
 411→    this.cardsContainer.add(cardBg);
 412→
 413→    // 선택 하이라이트 (흰 테두리)
 414→    const highlight = this.add.rectangle(x, y, WP_CARD_W, WP_CARD_H, 0, 0);
 415→    highlight.setStrokeStyle(3, 0xffffff);
 416→    highlight.setVisible(isSelected);
 417→    this.wpHighlights.set(wp.id, highlight);
 418→    this.cardsContainer.add(highlight);
 419→
 420→    // 세로 이미지 (bgKey) — 카드 상단을 채우는 portrait 썸네일
 421→    if (this.textures.exists(wp.bgKey)) {
 422→      const thumb = this.add.image(x, y - 11, wp.bgKey)
 423→        .setDisplaySize(WP_CARD_W - 4, WP_CARD_H - 22);
 424→      if (!isOwned) { thumb.setTint(0x000000); thumb.setAlpha(0.5); }
 425→      this.cardsContainer.add(thumb);
 426→    }
 427→
 428→    // 미보유 자물쇠
 429→    if (!isOwned) {
 430→      const lock = this.add.text(x, y - 8, '🔒', { fontSize: '20px' }).setOrigin(0.5);
 431→      this.cardsContainer.add(lock);
 432→    }
 433→
 434→    // WP 배지 (우상단) — 기본 배경은 '기본', 가챠 배경은 'WP'
 435→    const isDefault = (DEFAULT_WP_IDS as readonly string[]).includes(wp.id);
 436→    const badgeText  = isDefault ? '기본' : 'WP';
 437→    const badgeColor = isDefault ? '#aaaaaa' : WP_ACCENT_HEX;
 438→    const badge = this.add.text(x + WP_CARD_W / 2 - 2, y - WP_CARD_H / 2 + 2, badgeText, {
 439→      fontSize: '9px', color: badgeColor, fontStyle: 'bold',
 440→      backgroundColor: '#000000cc', padding: { x: 3, y: 1 },
 441→    }).setOrigin(1, 0);
 442→    this.cardsContainer.add(badge);
 443→
 444→    // 하단 반투명 바 + 이름
 445→    const barY = y + WP_CARD_H / 2 - 11;
 446→    const bar = this.add.rectangle(x, barY, WP_CARD_W, 22, 0x000000, 0.75);
 447→    this.cardsContainer.add(bar);
 448→    const nameText = this.add.text(x, barY, wp.name, {
 449→      fontSize: '11px',
 450→      color: isOwned ? WP_ACCENT_HEX : '#444444',
 451→      fontStyle: 'bold',
 452→    }).setOrigin(0.5);
 453→    this.cardsContainer.add(nameText);
 454→
 455→    // 클릭 이벤트
 456→    cardBg.setInteractive({ useHandCursor: isOwned });
 457→    if (isOwned) {
 458→      cardBg.on('pointerover', () => cardBg.setFillStyle(0x252540));
 459→      cardBg.on('pointerout',  () => cardBg.setFillStyle(0x1a1a2e));
 460→    }
 461→    cardBg.on('pointerup', () => {
 462→      if (!this.hasDragged && this.hasPointerDownInScene) this.showWallpaperDetail(wp);
 463→    });
 464→  }
