 685→  private selectCharacter(id: string) {
 686→    // 이전 선택 하이라이트 제거
 687→    const prev = this.cardHighlights.get(this.selectedId);
 688→    if (prev) prev.setVisible(false);
 689→
 690→    this.selectedId = id;
 691→    setSelectedCharacter(id);
 692→
 693→    const next = this.cardHighlights.get(id);
 694→    if (next) next.setVisible(true);
 695→
 696→    // 헤더 직접 갱신 (씬 재시작 없이)
 697→    const def = CHARACTERS.find(c => c.id === id) ?? CHARACTERS[0];
