 842→  /** GachaScene.fitVideoToCanvas와 동일 — aspect ratio 유지하며 400×600 캔버스에 cover */
 843→  private fitVideoToPanel(vid: Phaser.GameObjects.Video): void {
 844→    const W = 400, H = 600;
 845→    vid.setDisplaySize(W, H);
 846→
 847→    const applyContain = () => {
 848→      // eslint-disable-next-line @typescript-eslint/no-explicit-any
 849→      const el: HTMLVideoElement | null = (vid as any).video ?? null;
 850→      const nw = el?.videoWidth  || 0;
 851→      const nh = el?.videoHeight || 0;
 852→      if (nw > 0 && nh > 0) {
 853→        const scale = Math.max(W / nw, H / nh);
 854→        vid.setDisplaySize(Math.round(nw * scale), Math.round(nh * scale));
 855→      }
 856→    };
 857→
 858→    vid.once('play', applyContain);
 859→    this.fitVideoTimers.push(this.time.delayedCall(100, applyContain));
 860→    this.fitVideoTimers.push(this.time.delayedCall(500, applyContain));
 861→  }
