 867→
 868→    // 비디오 명시 정지 및 HTMLVideoElement src 해제
 869→    if (this.detailVideo) {
 870→      this.detailVideo.stop();
 871→      // eslint-disable-next-line @typescript-eslint/no-explicit-any
