111→    this.goldCollected = 0;
112→    this.cheatSuspicionCount = 0;
113→    this.diamondCollected = 0;
114→    this.topazCollected = 0;
115→    this.rainbowCollected = 0;
116→    this.sessionPromise = null; // 재시작 시 이전 세션 프로미스 해제
117→    // 디버그 Graphics 참조 초기화 (씬 재시작 시 이전 객체는 Phaser가 파괴하므로 참조만 해제)
118→    this.manualHitboxDebug = undefined;
