156→  preload() {
157→    // 선택된 배경화면 조건부 로딩 (DifficultySelectScene에서 미리 로드 안 된 경우 fallback)
158→    const wpDef = this.selectedWpId ? getWallpaperDef(this.selectedWpId) : null;
159→    if (wpDef && !this.textures.exists(wpDef.bgKey)) {
160→      this.load.image(wpDef.bgKey, wpDef.bgPath);
161→    }
162→
163→    // DifficultySelectScene에서 미리 로딩됨. 캐시에 없을 경우에만 fallback 로딩.
164→
165→    if (this.difficulty === Difficulty.NORMAL && !this.textures.exists('background3')) {
166→      this.load.image('background3', 'assets/backgrounds/background3.webp');
167→    } else if (this.difficulty === Difficulty.HARD && !this.textures.exists('background')) {
168→      this.load.image('background', 'assets/backgrounds/background.webp');
169→    } else if (this.difficulty === Difficulty.EXTREME && !this.textures.exists('background2')) {
170→      this.load.image('background2', 'assets/backgrounds/background2.webp');
171→    }
172→    if (this.difficulty === Difficulty.EXTREME && isChristmasSeason() && !this.textures.exists('xmas_background')) {
173→      this.load.image('xmas_background', 'assets/backgrounds/xmas_background.webp');
174→    }
175→
176→    // Player assets
177→    const CHARS_WITH_SPRITES = GameScene.CHARS_WITH_SPRITES;
178→    if (CHARS_WITH_SPRITES.includes(this.selectedCharId)) {
179→      const p = `${this.selectedCharId}_`;
180→      if (!this.textures.exists(`${p}front`)) this.load.image(`${p}front`, `assets/players/${p}front.webp`);
181→      if (!this.textures.exists(`${p}left`)) this.load.image(`${p}left`, `assets/players/${p}left.webp`);
182→      if (!this.textures.exists(`${p}right`)) this.load.image(`${p}right`, `assets/players/${p}right.webp`);
183→    } else {
184→      // chibi (기본) 또는 플레이어 스프라이트가 없는 UR 캐릭터 → 치비로 fallback
185→      if (!this.textures.exists('front')) this.load.image('front', 'assets/players/chibi_front.webp');
186→      if (!this.textures.exists('left')) this.load.image('left', 'assets/players/chibi_left.webp');
187→      if (!this.textures.exists('right')) this.load.image('right', 'assets/players/chibi_right.webp');
188→    }
189→
190→    if (!this.textures.exists('poop')) this.load.image('poop', 'assets/poops/poop.webp');
191→    if (!this.textures.exists('poop_glasses')) this.load.image('poop_glasses', 'assets/poops/poop_glasses.webp');
192→    if (!this.textures.exists('poop_sunglass')) this.load.image('poop_sunglass', 'assets/poops/poop_sunglass.webp');
193→    if (!this.textures.exists('poop_sunglass2')) this.load.image('poop_sunglass2', 'assets/poops/poop_sunglass2.webp');
194→    if (!this.textures.exists('poop_smile')) this.load.image('poop_smile', 'assets/poops/poop_smile.webp');
195→    if (!this.textures.exists('gold_poop')) this.load.image('gold_poop', 'assets/poops/gold_poop.webp');
196→    if (!this.textures.exists('diamond_poop')) this.load.image('diamond_poop', 'assets/poops/diamond_poop.webp');
197→    if (!this.textures.exists('topaz_poop')) this.load.image('topaz_poop', 'assets/poops/topaz.webp');
198→    if (!this.textures.exists('rainbow_poop')) this.load.image('rainbow_poop', 'assets/poops/rainbow_poop.webp');
199→
200→    if (this.difficulty === Difficulty.EXTREME && isChristmasSeason()) {
201→      if (!this.textures.exists('xmas_poop_ribbon')) this.load.image('xmas_poop_ribbon', 'assets/poops/xmas_present_poop.webp');
202→      if (!this.textures.exists('xmas_poop_nose')) this.load.image('xmas_poop_nose', 'assets/poops/xmas_nose_poop.webp');
