206→    }
207→
208→    // BGM
209→    if (this.difficulty === Difficulty.EXTREME && isChristmasSeason()) {
210→      if (!this.cache.audio.exists('xmasBgMusic')) this.load.audio('xmasBgMusic', 'assets/bgms/xmas_poop.mp3');
