483→  update() {
484→    if (!this.gameOver) {
485→      this.player.update();
486→
487→      // 탭 숨김 중엔 모든 게임 로직 차단 (rAF throttle로 인한 오탐 및 타이밍 레이스 방지)
488→      if (document.hidden) return;
489→
490→      // [안티치트 레이어 3] Phaser 내부 함수 변조 감지
491→      // 모듈 로드 시 캡처한 원본과 다르면 콘솔 치트가 prototype을 덮어쓴 것
492→      if (
493→        Phaser.Physics.Arcade.World.prototype.overlap    !== _origOverlap ||
494→        Phaser.Physics.Arcade.World.prototype.intersects !== _origIntersects
495→      ) {
496→        this.handleCheatDetected();
497→        return;
498→      }
499→
500→      // [안티치트 레이어 4] 물리 엔진 강제 일시정지 감지
501→      // 치트 shield 루프가 setInterval로 physics.world.pause()를 반복 호출할 때 차단
502→      if (this.physics.world.isPaused) {
503→        this.handleCheatDetected();
504→        return;
505→      }
506→
507→      // [안티치트 레이어 5] 수동 AABB 충돌 감지
508→      // physics.overlap이 변조되거나 body가 비활성화되어도 스프라이트 좌표로 직접 계산
509→      this.checkManualPoopCollision();
510→      if (this.gameOver) return;
511→
512→      // realNow(): 모듈 로드 시점에 캡처한 원본 Date.now — 콘솔 조작 무효
513→      const now = realNow();
514→
515→      // 레이어 1: realNow() 기반 점수 계산 (Date.now 조작 무력화)
516→      const elapsed = now - this.lastScoreTime;
517→      if (elapsed >= 100) {
518→        const points = Math.floor(elapsed / 100);
519→        this.lastScoreTime = now - (elapsed % 100); // 나머지 시간 이월
520→        this.updateScore(this.ability.getTickScore(points));
521→      }
522→
523→      // 캐릭터 능력 프레임 업데이트 (글리치 분신 추적 등)
524→      this.ability.onUpdate(this.abilityAPI);
525→
526→      // 레이어 2: rAF 조작 감지 (5초마다 구간 비율 체크)
527→      // realNow vs Phaser time 비교 — Date.now·performance.now 동시 조작도 감지
528→      if (now - this.lastCheatCheckTime >= 5000) {
529→        const realInterval = now - this.lastCheatCheckTime;
530→        const phaserInterval = this.time.now - this.lastPhaserCheckTime;
531→        const ratio = phaserInterval / realInterval;
532→
533→        // 정상 범위: 0.70 ~ 1.30 (모바일 OS 스로틀 허용)
534→        // ratio < 0.70: rAF 슬로우 조작 (slow-motion 치트)
535→        // ratio > 1.30: rAF 패스트 조작 (fast-forward 치트)
536→        // 연속 2회 이상 탐지시에만 차단 (일시적 OS 스로틀 오탐 방지)
537→        if (ratio < 0.70 || ratio > 1.30) {
538→          this.cheatSuspicionCount++;
539→          console.warn('[Anti-cheat] rAF 이상 감지:', ratio.toFixed(2), `(${this.cheatSuspicionCount}회 연속)`);
540→          if (this.cheatSuspicionCount >= 2) {
541→            this.handleCheatDetected();
542→            return;
543→          }
544→        } else {
545→          this.cheatSuspicionCount = 0; // 정상 구간 → 연속 카운터 초기화
546→        }
547→        // 기준점 갱신은 정상/이상 구분 없이 항상 수행
548→        this.resetCheatCheckpoints();
549→      }
550→    }
551→  }
