  // 숨김 시: 기준점만 리셋 (lastScoreTime 보존 → 숨기기 직전 이월분 유지)
  // 복귀 시: lastScoreTime도 리셋 (숨김 동안 누적 시간을 점수에 반영하지 않음)
  const onVisibilityChange = () => {
    if (!this.gameOver) {
      if (!document.hidden) {
        this.lastScoreTime = realNow();
      }
      this.resetCheatCheckpoints();
    }
