1549→  /**
1550→   * 재시작 버튼 표시 (다시 하기 + 메인 메뉴) - 버튼 스타일
1551→   * @param isNewRecord 새 기록 달성 여부 (SKOR 텍스트 위치에 따라 버튼 y 조정)
1552→   */
1553→  private showRestartButton(isNewRecord = false) {
1554→    // 새 기록 시: SKOR 텍스트(y≈418) + 퀘스트(y≈441) 아래 배치
1555→    // 일반 시: SKOR 텍스트(y≈380) + 퀘스트(y≈403) 아래 배치
1556→    const retryY = isNewRecord ? 470 : 455;
1557→    const menuY  = isNewRecord ? 548 : 535;
1558→
1559→    // 다시 하기 버튼 배경
1560→    const retryButtonBg = this.add.rectangle(200, retryY, 250, 70, 0x00aa00)
1561→      .setOrigin(0.5)
1562→      .setDepth(199)
1563→      .setStrokeStyle(3, 0xffffff);
1564→
1565→    // 다시 하기 버튼 텍스트
1566→    const retryButtonText = this.add.text(200, retryY, '다시 하기', {
1567→      fontSize: '22px',
1568→      color: '#ffffff',
1569→      fontStyle: 'bold'
1570→    }).setOrigin(0.5).setDepth(200);
1571→
1572→    // 다시 하기 버튼 인터랙티브 영역 (배경을 클릭 가능하게)
1573→    retryButtonBg.setInteractive({ useHandCursor: true });
1574→
1575→    // 메인 메뉴 버튼 배경
1576→    const menuButtonBg = this.add.rectangle(200, menuY, 250, 70, 0x555555)
1577→      .setOrigin(0.5)
1578→      .setDepth(199)
1579→      .setStrokeStyle(3, 0xffffff);
1580→
1581→    // 메인 메뉴 버튼 텍스트
1582→    const menuButtonText = this.add.text(200, menuY, '메인 메뉴', {
1583→      fontSize: '22px',
1584→      color: '#ffffff',
1585→      fontStyle: 'bold'
1586→    }).setOrigin(0.5).setDepth(200);
1587→
1588→    // 메인 메뉴 버튼 인터랙티브 영역
1589→    menuButtonBg.setInteractive({ useHandCursor: true });
1590→
1591→    // 호버 효과 - 다시 하기 버튼
1592→    retryButtonBg.on('pointerover', () => {
1593→      retryButtonBg.setFillStyle(0x00ff00);
1594→      retryButtonBg.setScale(1.05);
1595→      retryButtonText.setScale(1.05);
1596→    });
1597→    retryButtonBg.on('pointerout', () => {
1598→      retryButtonBg.setFillStyle(0x00aa00);
1599→      retryButtonBg.setScale(1);
1600→      retryButtonText.setScale(1);
1601→    });
1602→
1603→    // 호버 효과 - 메인 메뉴 버튼
1604→    menuButtonBg.on('pointerover', () => {
1605→      menuButtonBg.setFillStyle(0x777777);
1606→      menuButtonBg.setScale(1.05);
1607→      menuButtonText.setScale(1.05);
1608→    });
1609→    menuButtonBg.on('pointerout', () => {
1610→      menuButtonBg.setFillStyle(0x555555);
1611→      menuButtonBg.setScale(1);
1612→      menuButtonText.setScale(1);
1613→    });
