 38→    return [
 39→      { x:  0,         y: -h        },
 40→      { x:  w * 0.55,  y: -h * 0.1  },
 41→      { x:  w * 0.75,  y:  h * 0.35 },
 42→      { x:  w * 0.3,   y:  h        },
 43→      { x: -w * 0.3,   y:  h        },
