    ring.setPosition(cx, cy);
    ring.setScale(1.9);
    ring.setAlpha(0);

    scene.tweens.add({
      targets: ring, scaleX: 1, scaleY: 1, alpha: 1,
      duration: 210, ease: 'Quad.easeIn',
      onComplete: () => {
        scene.tweens.add({ targets: ring, alpha: 0, duration: 160, onComplete: () => ring.destroy() });
      },
    });

